          <td style="color: var(--text);">${product.商品名 || ""}</td>
          <td style="color: var(--text-muted);">${getProductCategory(product.商品カテゴリID)}</td>
          <td style="color: var(--text);">${currentStock}</td>
          <td style="color: var(--text);">${predictedQty}</td>
          <td style="color: var(--text); font-weight: bold;">${recommendedQty}</td>
          <td>
            <input type="number" class="input order-quantity" data-id="${product.商品ID}" 
                   value="${recommendedQty}" min="0" style="width: 80px;">
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="use-recommended">推奨</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-id="${product.商品ID}" 
                   placeholder="発注理由" style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-id="${product.商品ID}">発注</button>
            <button class="action-btn secondary" onclick="window.showScreen('scr-1778591896813')">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 商品カテゴリ名を取得（仮実装）
  function getProductCategory(categoryId) {
    const categories = {
      "cat1": "食品",
      "cat2": "日用品", 
      "cat3": "衣料品",
      "cat4": "家電"
    };
    return categories[categoryId] || "その他";
  }

  // 検索・絞り込み処理
  async function searchProducts() {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const dateStart = container.querySelector("#input-date-start").value;
    const dateEnd = container.querySelector("#input-date-end").value;
    const searchKeyword = container.querySelector("#input-search").value.toLowerCase();

    // 日付バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      showError("終了日は開始日以降の日付を入力してください");
      return;
    }

    if (!storeId) {
      container.querySelector("#table-container").classList.add("hidden");
      container.querySelector("#no-store-message").classList.remove("hidden");
      return;
    }

    try {
      const allProducts = await window.aivicApi.list(2) || []; // 商品マスタ
      let filteredProducts = allProducts.filter(p => p.有効フラグ);

      // カテゴリ絞り込み
      if (category) {
        filteredProducts = filteredProducts.filter(p => getProductCategory(p.商品カテゴリID) === category);
      }

      // 商品名検索
      if (searchKeyword) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品名 || "").toLowerCase().includes(searchKeyword) ||
          (p.商品コード || "").toLowerCase().includes(searchKeyword)
        );
      }

      currentProducts = filteredProducts;
      renderProducts(filteredProducts);
      hideError();

      // 需要予測結果の表示
      showPredictionResults(storeId, filteredProducts);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // 需要予測結果表示
  function showPredictionResults(storeId, products) {
    const predictionArea = container.querySelector("#prediction-area");
    const predictionContent = container.querySelector("#prediction-content");

    if (products.length === 0) {
      predictionArea.classList.add("hidden");
      return;
    }

    const storePredictions = predictions.filter(p => p.店舗ID === storeId);
    const totalPredicted = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalRecommended = storePredictions.reduce((sum, p) => sum + (p.推奨発注数量 || 0), 0);

    predictionContent.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPredicted}</div>
          <div style="color: var(--text-muted);">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalRecommended}</div>
          <div style="color: var(--text-muted);">総推奨発注量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--text);">${products.length}</div>
          <div style="color: var(--text-muted);">対象商品数</div>
        </div>
      </div>
    `;

    predictionArea.classList.remove("hidden");
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  function hideError() {
    container.querySelector("#error-message").classList.add("hidden");
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    if (!quantity || quantity <= 0) {
      showError("発注量は正の数値を入力してください");
      return false;
    }

    if (isNaN(quantity)) {
      showError("発注量は数値で入力してください");
      return false;
    }

    const storeId = container.querySelector("#select-store").value;
    const product = currentProducts.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);

    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      需要予測結果ID: prediction ? prediction.予測結果ID : null,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (product?.リードタイム日数 || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: parseInt(quantity),
      予測数量: prediction ? prediction.予測数量 : 0,
      発注単価: product?.単価 || 0,
      発注金額: parseInt(quantity) * (product?.単価 || 0),
      発注方法: prediction && parseInt(quantity) === prediction.推奨発注数量 ? "AI推奨採用" : "AI推奨修正",
      発注ステータス: "発注済",
      仕入先ID: product?.仕入先ID || "",
      発注理由: reason || "",
      自動発注フラグ: false,
      作成者ID: "current-user",
      更新者ID: "current-user"
    };

    try {
      const saved = await window.aivicApi.save(9, orderData);
      if (saved) {
        return true;
      } else {
        showError("発注処理に失敗しました");
        return false;
      }
    } catch (error) {
      console.error("発注エラー:", error);
      showError("発注処理中にエラーが発生しました");
      return false;
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentProducts.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "カテゴリ", "現在在庫", "予測需要量", "推奨発注量"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...currentProducts.map(product => {
        const prediction = predictions.find(p => p.商品ID === product.商品ID);
        return [
          `"${product.商品コード || ""}"`,
          `"${product.商品名|| ""}"`,
          `"${getProductCategory(product.商品カテゴリID)}"`,
          Math.floor(Math.random() * 100) + 10,
          prediction ? prediction.予測数量 : 0,
          prediction ? prediction.推奨発注数量 : 0
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initializeData();

  // イベントリスナー
  container.querySelector("#select-store").addEventListener("change", searchProducts);

  container.querySelector("#btn-search").addEventListener("click", searchProducts);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#select-store").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelector("#input-date-start").value = "";
    container.querySelector("#input-date-end").value = "";
    container.querySelector("#input-search").value = "";
    container.querySelector("#table-container").classList.add("hidden");
    container.querySelector("#no-store-message").classList.remove("hidden");
    container.querySelector("#prediction-area").classList.add("hidden");
    hideError();
  });

  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 全選択チェックボックス
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".product-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括発注
  container.querySelector("#btn-bulk-order").addEventListener("click", async () => {
    const checkedBoxes = container.querySelectorAll(".product-checkbox:checked");
    if (checkedBoxes.length === 0) {
      showError("発注する商品を選択してください");
      return;
    }

    let successCount = 0;
    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.id;
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-id="${productId}"]`);

      const success = await processOrder(productId, quantityInput.value, reasonInput.value);
      if (success) successCount++;
    }

    if (successCount > 0) {
      alert(`${successCount}件の発注を完了しました`);
      searchProducts(); // 画面更新
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 推奨発注量設定
    if (e.target.classList.contains("adjust-btn")) {
      const productId = e.target.dataset.id;
      const prediction = predictions.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      if (prediction && quantityInput) {
        quantityInput.value = prediction.推奨発注数量 || 0;
      }
    }

    // 個別発注
    if (e.target.classList.contains("order-btn")) {
      const productId = e.target.dataset.id;
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-id="${productId}"]`);

      const product = currentProducts.find(p => p.商品ID === productId);

      // 発注確認モーダル表示
      const modal = container.querySelector("#order-modal");
      const orderDetails = container.querySelector("#order-details");

      orderDetails.innerHTML = `
        <p><strong>商品名:</strong> ${product?.商品名 || ""}</p>
        <p><strong>商品コード:</strong> ${product?.商品コード || ""}</p>
        <p><strong>発注数量:</strong> ${quantityInput.value}</p>
        <p><strong>発注理由:</strong> ${reasonInput.value || "なし"}</p>
      `;

      modal.classList.remove("hidden");

      // 発注確定処理
      const confirmBtn = container.querySelector("#btn-confirm-order");
      const cancelBtn = container.querySelector("#btn-cancel-order");

      const newConfirmHandler = async () => {
        const success = await processOrder(productId, quantityInput.value, reasonInput.value);
        if (success) {
          alert("発注が完了しました");
          modal.classList.add("hidden");
          searchProducts(); // 画面更新
        }
        confirmBtn.removeEventListener("click", newConfirmHandler);
      };

      const newCancelHandler = () => {
        modal.classList.add("hidden");
        cancelBtn.removeEventListener("click", newCancelHandler);
      };

      confirmBtn.addEventListener("click", newConfirmHandler);
      cancelBtn.addEventListener("click", newCancelHandler);
    }
  });

  // 入力値バリデーション
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity")) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseFloat(value) < 0)) {
        e.target.style.borderColor = "#ff6b6b";
        showError("発注量は0以上の数値を入力してください");
      } else {
        e.target.style.borderColor = "";
        hideError();
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#filter-user");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      updatePagination(0);
      return;
    }

    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const userName = getUserName(row.ユーザーID);
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultBadge = getResultBadge(row.処理結果);

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td>${resultBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updatePagination(rows.length);
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : 'Unknown';
  }

  // 処理結果のバッジを生成
  function getResultBadge(result) {
    if (!result) return '';

    let badgeColor = '';
    switch (result) {
      case '成功':
        badgeColor = 'background: #28a745; color: white;';
        break;
      case '失敗':
        badgeColor = 'background: #dc3545; color: white;';
        break;
      case 'エラー':
        badgeColor = 'background: #ffc107; color: black;';
        break;
      default:
        badgeColor = 'background: var(--bg-main); color: var(--text);';
    }

    return `<span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; ${badgeColor}">${result}</span>`;
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(1, totalPages)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;

    if (totalPages <= 1) {
      container.querySelector("#pagination").style.display = 'none';
    } else {
      container.querySelector("#pagination").style.display = 'flex';
    }
  }

  // フィルタリング処理
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const userId = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value.toLowerCase();
    const result = container.querySelector("#filter-result").value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を指定してください。');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = new Date(row.操作日時);
        if (startDate && rowDate < new Date(startDate)) return false;
        if (endDate && rowDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && row.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && (!row.操作画面 || !row.操作画面.toLowerCase().includes(screenName))) return false;

      // IPアドレスフィルター
      if (ipAddress) {
        // IPアドレス形式の簡単な妥当性チェック
        const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
        if (ipAddress && !ipPattern.test(ipAddress) && ipAddress !== '') {
          // 部分一致も許可
          if (!row.IPアドレス || !row.IPアドレス.toLowerCase().includes(ipAddress)) return false;
        } else {
          if (row.IPアドレス !== ipAddress) return false;
        }
      }

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector("#detail-modal");
    const userName = getUserName(history.ユーザーID);
    const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

    container.querySelector("#detail-id").textContent = history.操作履歴ID || '';
    container.querySelector("#detail-datetime").textContent = operationDate;
    container.querySelector("#detail-user").textContent = userName;
    container.querySelector("#detail-store").textContent = history.店舗ID || '全店舗';
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-content-text").textContent = history.操作内容 || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';

    modal.classList.remove("hidden");
  }

  // CSV出力
  function exportCSV() {
    if (!filteredData || filteredData.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredData.length > 100000) {
      alert('データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでから再度お試しください。');
      return;
    }

    const headers = [
      '操作履歴ID', '操作日時', 'ユーザー名', '店舗ID', '操作種別', '操作画面',
      '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント',
      '処理結果', 'エラーメッセージ', '処理時間'
    ];

    const csvContent = [
      headers.join(','),
      ...filteredData.map(row => {
        const userName = getUserName(row.ユーザーID);
        const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${row.操作履歴ID || ''}"`,
          `"${operationDate}"`,
          `"${userName}"`,
          `"${row.店舗ID || ''}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.操作対象テーブル || ''}"`,
          `"${row.操作対象ID || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${row.IPアドレス || ''}"`,
          `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${row.処理時間 || ''}"`
        ].join(',');
      })
    ].join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const historyRows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (historyRows) {
        allHistoryData = historyRows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      } else {
        allHistoryData = tables[12]?.records || [];
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      }
    } catch (error) {
      console.error('操作履歴データの取得に失敗しました:', error);
      allHistoryData = tables[12]?.records || [];
      filteredData = [...allHistoryData];
      renderRows(filteredData);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-user").value = '';
    container.querySelector("#filter-operation-type").value = '';
    container.querySelector("#filter-screen-name").value = '';
    container.querySelector("#filter-ip-address").value = '';
    container.querySelector("#filter-result").value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderRows(filteredData);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers();
  loadData();
}

function(container, apiUrl, tables) {
