        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.店舗ID;
            option.textContent = store.店舗名;
            storeSelect.appendChild(option);
          }
        });
      }

      // 商品データを取得してカテゴリを設定
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');
      if (products) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID))];
        categories.forEach(categoryId => {
          const label = document.createElement('label');
          label.style.cssText = 'color: var(--text); display: block; margin-bottom: 5px;';
          label.innerHTML = `<input type="checkbox" name="product-category" value="${categoryId}"> カテゴリ${categoryId.slice(-8)}`;
          categoryContainer.appendChild(label);
        });
      }

      // デフォルト日付設定
      const today = new Date();
      const tomorrow = new Date(today);
      tomorrow.setDate(today.getDate() + 1);
      const nextWeek = new Date(today);
      nextWeek.setDate(today.getDate() + 7);
      const lastMonth = new Date(today);
      lastMonth.setMonth(today.getMonth() - 1);

      container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
      container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
      container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
      container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

    } catch (error) {
      showError('初期データの読み込みに失敗しました。');
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    container.querySelector('#success-message').style.display = 'none';
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.style.display = 'block';
    container.querySelector('#error-message').style.display = 'none';
  }

  // メッセージクリア
  function clearMessages() {
    container.querySelector('#error-message').style.display = 'none';
    container.querySelector('#success-message').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    clearMessages();

    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('input[name="product-category"]:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;

    if (!predictionStartDate || !predictionEndDate) {
      showError('予測対象期間を設定してください。');
      return false;
    }

    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }

    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください。');
      return false;
    }

    if (!selectedModel) {
      showError('予測モデルを選択してください。');
      return false;
    }

    if (!learningStartDate || !learningEndDate) {
      showError('学習データ期間の開始日と終了日を入力してください。');
      return false;
    }

    // 日付バリデーション
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const predStart = new Date(predictionStartDate);
    const predEnd = new Date(predictionEndDate);
    const learnStart = new Date(learningStartDate);
    const learnEnd = new Date(learningEndDate);

    if (predStart < today) {
      showError('予測期間に過去の日付は指定できません。');
      return false;
    }

    if (predEnd < predStart) {
      showError('予測期間の終了日は開始日以降を設定してください。');
      return false;
    }

    // 予測期間が1年超チェック
    const oneYearLater = new Date(predStart);
    oneYearLater.setFullYear(oneYearLater.getFullYear() + 1);
    if (predEnd > oneYearLater) {
      showError('予測期間は1年以内で設定してください。');
      return false;
    }

    // 学習データ期間チェック
    const learningDays = Math.ceil((learnEnd - learnStart) / (1000 * 60 * 60 * 24));
    const predictionDays = Math.ceil((predEnd - predStart) / (1000 * 60 * 60 * 24));

    if (learningDays < predictionDays) {
      showError('学習データ期間は予測期間以上に設定してください。');
      return false;
    }

    return true;
  }

  // 進捗バー表示/更新
  function showProgress(percentage, message) {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressContainer.style.display = 'block';
    progressBar.style.width = percentage + '%';
    progressText.textContent = message;
  }

  // 進捗バー非表示
  function hideProgress() {
    container.querySelector('#progress-container').style.display = 'none';
  }

  // UI無効化/有効化
  function setUIEnabled(enabled) {
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      if (enabled) {
        input.removeAttribute('disabled');
      } else {
        input.setAttribute('disabled', 'disabled');
      }
    });
    isProcessing = !enabled;
  }

  // 予測結果表示
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#results-tbody');
    const resultsCard = container.querySelector('#prediction-results');

    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">予測結果がありません</td></tr>';
    } else {
      tbody.innerHTML = results.map(result => `
        <tr data-id="${result.予測結果ID}">
          <td>${result.店舗名 || ''}</td>
          <td>${result.商品名 || ''}</td>
          <td>${result.予測対象日 ? new Date(result.予測対象日).toLocaleDateString() : ''}</td>
          <td>${result.予測数量 || 0}</td>
          <td>${result.予測精度 || 0}%</td>
          <td>${result.推奨発注数量 || 0}</td>
          <td>
            <button class="action-btn secondary view-detail-btn" data-id="${result.予測結果ID}">詳細</button>
          </td>
        </tr>
      `).join('');
    }

    resultsCard.style.display = 'block';
  }

  // AI予測実行処理
  async function executePrediction() {
    if (!validateForm()) return;
    if (isProcessing) return;

    setUIEnabled(false);
    clearMessages();

    try {
      // 進捗表示開始
      showProgress(0, '予測処理を開始しています...');

      // フォームデータ収集
      const formData = {
        店舗ID: container.querySelector('#store-select').value,
        予測対象開始日: container.querySelector('#prediction-start-date').value,
        予測対象終了日: container.querySelector('#prediction-end-date').value,
        商品カテゴリ: Array.from(container.querySelectorAll('input[name="product-category"]:checked')).map(cb => cb.value),
        予測モデル: container.querySelector('input[name="prediction-model"]:checked').value,
        学習データ開始日: container.querySelector('#learning-start-date').value,
        学習データ終了日: container.querySelector('#learning-end-date').value,
        季節要因係数: parseFloat(container.querySelector('#seasonal-slider').value),
        予測精度閾値: parseInt(container.querySelector('#accuracy-threshold').value)
      };

      // 段階的な進捗更新をシミュレート
      showProgress(20, 'データを準備しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(40, '学習データを読み込んでいます...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      showProgress(60, 'AIモデルを実行しています...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      showProgress(80, '予測結果を生成しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      // 予測結果データを生成（実際の実装ではAPIから取得）
      const mockResults = [];
      for (let i = 0; i < 5; i++) {
        const result = await window.aivicApi.save(10, { // 需要予測結果テーブル
          店舗ID: formData.店舗ID,
          商品ID: `product-${i + 1}`,
          予測対象日: formData.予測対象開始日,
          予測数量: Math.floor(Math.random() * 100) + 50,
          予測精度: Math.floor(Math.random() * 30) + 70,
          推奨発注数量: Math.floor(Math.random() * 80) + 40,
          予測モデルバージョン: formData.予測モデル + '-v1.0',
          予測ステータス: '完了',
          発注済フラグ: false
        });

        if (result) {
          result.店舗名 = '店舗A';
          result.商品名 = `商品${i + 1}`;
          mockResults.push(result);
        }
      }

      showProgress(100, '予測処理が完了しました。');
      await new Promise(resolve => setTimeout(resolve, 500));

      hideProgress();
      showSuccess(`AI需要予測が正常に完了しました。${mockResults.length}件の予測結果を生成しました。`);
      renderPredictionResults(mockResults);

    } catch (error) {
      hideProgress();
      showError('AI予測実行に失敗しました。システム管理者にお問い合わせください。');
    } finally {
      setUIEnabled(true);
    }
  }

  // 天候データ取込処理
  async function importWeatherData() {
    if (isProcessing) return;

    try {
      showSuccess('天候データの取込を開始しました...');

      // 模擬的な天候データ取込
      const weatherData = await window.aivicApi.save(4, { // 天候データテーブル
        店舗ID: container.querySelector('#store-select').value || 'default-store',
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '実績値',
        データソース: '気象庁API'
      });

      if (weatherData) {
        showSuccess('天候データの取込が正常に完了しました。');
      } else {
        showError('天候データの取得に失敗しました。データソースの設定を確認してください。');
      }
    } catch (error) {
      showError('天候データの取得に失敗しました。データソースの設定を確認してください。');
    }
  }

  // イベントデータ取込処理
  async function importEventData() {
    if (isProcessing) return;

    try {
      showSuccess('イベントデータの取込を開始しました...');

      // 模擬的なイベントデータ取込
      const eventData = await window.aivicApi.save(5, { // イベントデータテーブル
        店舗ID: container.querySelector('#store-select').value || 'default-store',
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 86400000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 500,
        有効フラグ: true,
        作成者: 'system',
        更新者: 'system'
      });

      if (eventData) {
        showSuccess('イベントデータの取込が正常に完了しました。');
      } else {
        showError('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
      }
    } catch (error) {
      showError('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-weather-import').addEventListener('click', importWeatherData);
  container.querySelector('#btn-event-import').addEventListener('click', importEventData);

  // 季節要因スライダー
  container.querySelector('#seasonal-slider').addEventListener('input', function() {
    container.querySelector('#seasonal-value').textContent = this.value;
  });

  // 予測結果の詳細表示
  container.addEventListener('click', function(e) {
    const detailBtn = e.target.closest('.view-detail-btn');
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      window.showScreen('scr-1778591838939'); // 需要予測管理画面に遷移
    }
  });

  // 初期化実行
  initializeData();
}

function(container, apiUrl, tables) {
