  // 成功メッセージ表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector("#error-messages");
    errorDiv.innerHTML = `<div style="background: rgba(0, 255, 0, 0.1); border: 1px solid #44ff44; padding: 10px; border-radius: 5px; color: var(--text); margin: 10px 0;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = "", 3000);
  }

  // バリデーション関数
  function validateInputs() {
    const storeSelect = container.querySelector("#store-select");
    const periodStart = container.querySelector("#period-start");
    const periodEnd = container.querySelector("#period-end");
    const currentStock = container.querySelector("#current-stock");
    const safetyStock = container.querySelector("#safety-stock");
    const leadTime = container.querySelector("#lead-time");
    const seasonalFactor = container.querySelector("#seasonal-factor");

    if (!storeSelect.value) {
      showError("店舗を選択してください");
      return false;
    }

    if (!selectedProduct) {
      showError("商品を選択してください");
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError("対象期間を設定してください");
      return false;
    }

    if (currentStock.value < 0) {
      showError("在庫数は0以上の値を入力してください");
      return false;
    }

    if (isNaN(safetyStock.value) || safetyStock.value === "") {
      showError("安全在庫には数値を入力してください");
      return false;
    }

    if (leadTime.value < 1 || leadTime.value > 365) {
      showError("リードタイムは1日から365日の範囲で入力してください");
      return false;
    }

    const weatherFactor = container.querySelector("#weather-factor").value;
    const eventFactor = container.querySelector("#event-factor").value;

    if (weatherFactor < 0 || weatherFactor > 200) {
      showError("天候影響度は0%から200%の範囲で入力してください");
      return false;
    }

    if (eventFactor < 0 || eventFactor > 200) {
      showError("イベント影響度は0%から200%の範囲で入力してください");
      return false;
    }

    if (seasonalFactor.value < 0.1 || seasonalFactor.value > 10) {
      showError("季節補正係数は0.1から10の範囲で入力してください");
      return false;
    }

    const finalOrderQty = container.querySelector("#final-order-qty");
    if (finalOrderQty.value < 0) {
      showError("発注量は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 商品一覧の再描画
