        <td>${p.発注単位 || 1}</td>
      </tr>
    `).join("");
  }

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeData = stores;
      const storeSelect = container.querySelector("#store-select");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(s => `<option value="${s.id}">${s.店舗名}</option>`).join("");
    }
  }

  // 商品データの読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      productData = products;
      renderProducts(products);
    }
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();

  // スライダー値の表示更新
  container.querySelector("#weather-factor").addEventListener("input", (e) => {
    container.querySelector("#weather-value").textContent = e.target.value + "%";
  });

  container.querySelector("#event-factor").addEventListener("input", (e) => {
    container.querySelector("#event-value").textContent = e.target.value + "%";
  });

  // 商品検索
  container.querySelector("#btn-product-search").addEventListener("click", () => {
    const keyword = container.querySelector("#product-search").value.toLowerCase();
    if (!keyword) {
      renderProducts(productData);
      return;
    }

    const filtered = productData.filter(p => 
      (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
      (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
    );
    renderProducts(filtered);
  });

  // 絞り込み実行
  container.querySelector("#btn-filter").addEventListener("click", () => {
    const storeId = container.querySelector("#store-select").value;
    const categoryId = container.querySelector("#category-select").value;

    let filtered = productData;

    if (categoryId) {
      filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProducts(filtered);
  });

  // 商品選択
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("product-radio")) {
      const productId = e.target.value;
      selectedProduct = productData.find(p => p.id === productId);

      if (selectedProduct) {
        container.querySelector("#calculation-section").style.display = "block";
        // デフォルト値設定
        container.querySelector("#lead-time").value = selectedProduct.リードタイム日数 || 7;
      }
    }
  });

  // AI予測実行
  container.querySelector("#btn-ai-predict").addEventListener("click", async () => {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;

    // 需要予測結果を取得
    const forecasts = await window.aivicApi.list(8); // 需要予測結果
    if (forecasts) {
      const forecast = forecasts.find(f => 
        f.店舗ID === storeId && 
        f.商品ID === selectedProduct.id
      );

      if (forecast) {
        container.querySelector("#demand-forecast").textContent = forecast.予測数量 || 0;
        container.querySelector("#forecast-accuracy").textContent = forecast.予測精度 || 0;
        container.querySelector("#ai-recommendation").textContent = forecast.推奨発注数量 || 0;
        container.querySelector("#final-order-qty").value = forecast.推奨発注数量 || 0;
        container.querySelector("#result-section").style.display = "block";
      } else {
        // 模擬的な予測値を生成
        const mockForecast = Math.floor(Math.random() * 100) + 50;
        const mockAccuracy = Math.floor(Math.random() * 20) + 80;
        container.querySelector("#demand-forecast").textContent = mockForecast;
        container.querySelector("#forecast-accuracy").textContent = mockAccuracy;
        container.querySelector("#ai-recommendation").textContent = mockForecast;
        container.querySelector("#final-order-qty").value = mockForecast;
        container.querySelector("#result-section").style.display = "block";
      }
    }
  });

  // 計算実行
  container.querySelector("#btn-calculate").addEventListener("click", () => {
    if (!validateInputs()) return;

    const currentStock = parseInt(container.querySelector("#current-stock").value) || 0;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 7;
    const weatherFactor = parseInt(container.querySelector("#weather-factor").value) / 100;
    const eventFactor = parseInt(container.querySelector("#event-factor").value) / 100;
    const seasonalFactor = parseFloat(container.querySelector("#seasonal-factor").value) || 1.0;

    // 基本需要予測量を取得
    const baseDemand = parseInt(container.querySelector("#demand-forecast").textContent) || 0;

    // 調整後需要量の計算
    const adjustedDemand = Math.round(baseDemand * weatherFactor * eventFactor * seasonalFactor);

    // 発注量計算（需要量 + 安全在庫 - 現在在庫）
    const orderQty = Math.max(0, adjustedDemand + safetyStock - currentStock);

    container.querySelector("#ai-recommendation").textContent = orderQty;
    container.querySelector("#final-order-qty").value = orderQty;
    container.querySelector("#result-section").style.display = "block";

    showSuccess("発注量の計算が完了しました");
  });

  // 発注書作成
  container.querySelector("#btn-create-order").addEventListener("click", () => {
    if (!validateInputs()) return;
    window.showScreen("scr-1778591907544"); // 発注書作成画面
  });

  // 発注実行
  container.querySelector("#btn-execute-order").addEventListener("click", async () => {
    if (!validateInputs()) return;

    const orderData = {
      店舗ID: container.querySelector("#store-select").value,
      商品ID: selectedProduct.id,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + parseInt(container.querySelector("#lead-time").value) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: parseInt(container.querySelector("#final-order-qty").value),
      予測数量: parseInt(container.querySelector("#demand-forecast").textContent) || 0,
      発注単価: selectedProduct.単価 || 0,
      発注金額: (parseInt(container.querySelector("#final-order-qty").value) || 0) * (selectedProduct.単価 || 0),
      発注方法: "AI推奨採用",
      発注ステータス: "発注済",
      仕入先ID: selectedProduct.仕入先ID || "",
      発注理由: "AI需要予測に基づく自動発注",
      自動発注フラグ: false,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: "current-user",
      更新者ID: "current-user"
    };

    const saved = await window.aivicApi.save(9, orderData); // 発注データ
    if (saved) {
      showSuccess("発注が正常に実行されました");
      window.showScreen("scr-1778591960771"); // 発注実行画面
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const ORDER_DATA_TABLE = 7; // 発注データ

  let currentOrders = [];
  let stores = [];
  let products = [];

  // 発注日付を今日の日付に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択プルダウンの初期化
  async function initStoreSelect() {
    try {
      stores = await window.aivicApi.list(STORES_TABLE) || [];
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    } catch (error) {
      showMessage('店舗データの取得に失敗しました', 'error');
    }
  }

  // 商品マスタの取得
  async function loadProducts() {
    try {
      products = await window.aivicApi.list(PRODUCTS_TABLE) || [];
    } catch (error) {
      console.error('商品データの取得に失敗:', error);
    }
  }

  // 発注データの再描画
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">発注対象のデータがありません</td></tr>';
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      const statusClass = getStatusClass(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.発注ID}">
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" ${isDisabled}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${order.予測数量 || 0}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td>${(order.発注金額 || 0).toLocaleString()}円</td>
          <td><span class="status-badge ${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // ステータスのCSSクラスを取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み': return 'status-sent';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 選択状況とサマリーの更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
    const checkedBoxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');

    container.querySelector('#selected-count').textContent = checkedBoxes.length;

    let totalAmount = 0;
    checkedBoxes.forEach(checkbox => {
      const orderId = checkbox.dataset.id;
      const order = currentOrders.find(o => o.発注ID === orderId);
      if (order) {
        totalAmount += order.発注金額 || 0;
      }
    });

    container.querySelector('#total-amount').textContent = totalAmount.toLocaleString();

    // 全選択チェックボックスの状態更新
    const selectAllCheckbox = container.querySelector('#select-all-checkbox');
    if (checkboxes.length === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    } else if (checkedBoxes.length === checkboxes.length) {
      selectAllCheckbox.checked = true;
      selectAllCheckbox.indeterminate = false;
    } else if (checkedBoxes.length > 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = true;
    } else {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    }
  }

  // メッセージ表示
  function showMessage(message, type = 'info') {
    const messageArea = container.querySelector('#message-area');
    const messageContent = container.querySelector('#message-content');

    messageContent.className = `message-${type}`;
    messageContent.textContent = message;
    messageArea.classList.remove('hidden');

    // 3秒後に自動で非表示
    setTimeout(() => {
      messageArea.classList.add('hidden');
    }, 3000);
  }

  // 店舗選択時の処理
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    const storeId = e.target.value;
    const orderListArea = container.querySelector('#order-list-area');

    if (!storeId) {
      orderListArea.classList.add('hidden');
      return;
    }

    try {
      // 選択した店舗の発注データを取得
      const allOrders = await window.aivicApi.list(ORDER_DATA_TABLE) || [];
      currentOrders = allOrders.filter(order => 
        order.店舗ID === storeId && 
        order.発注日 && 
        order.発注日.startsWith(today)
      );

      renderOrders(currentOrders);
      orderListArea.classList.remove('hidden');

      if (currentOrders.length === 0) {
        showMessage('選択した店舗の発注データがありません', 'warning');
      }
    } catch (error) {
      showMessage('発注データの取得に失敗しました', 'error');
    }
  });

  // 全選択チェックボックスの処理
  container.querySelector('#select-all-checkbox').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
    checkboxes.forEach(checkbox => {
      checkbox.checked = e.target.checked;
    });
    updateSummary();
  });

  // 個別チェックボックスの処理
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      updateSummary();
    }
  });

  // 発注送信処理
  container.querySelector('#btn-send-orders').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');

    if (checkedBoxes.length === 0) {
      showMessage('発注する商品を選択してください', 'error');
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrderIds = Array.from(checkedBoxes).map(cb => cb.dataset.id);
    const duplicateOrders = currentOrders.filter(order => 
      selectedOrderIds.includes(order.発注ID) && order.発注ステータス === '送信済み'
    );

    if (duplicateOrders.length > 0) {
      showMessage('選択した発注データには既に送信済みのものが含まれています。重複送信はできません。', 'error');
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = currentOrders.filter(order => 
      selectedOrderIds.includes(order.発注ID) && (order.発注数量 || 0) === 0
    );

    if (zeroQuantityOrders.length > 0) {
      if (!confirm('発注数量が0の商品が含まれています。これらの商品は発注対象から除外されます。続行しますか？')) {
        return;
      }
      // 発注数量0の商品を除外
      const validOrderIds = selectedOrderIds.filter(id => 
        !zeroQuantityOrders.some(order => order.発注ID === id)
      );
      if (validOrderIds.length === 0) {
        showMessage('有効な発注データがありません', 'error');
        return;
      }
    }

    if (!confirm(`${checkedBoxes.length}件の発注を送信します。よろしいですか？`)) {
      return;
    }

    try {
      let successCount = 0;
      let errorCount = 0;

      // 各発注データのステータスを更新
      for (const checkbox of checkedBoxes) {
        const orderId = checkbox.dataset.id;
        const order = currentOrders.find(o => o.発注ID === orderId);

        if (order && (order.発注数量 || 0) > 0) {
          try {
            await window.aivicApi.update(ORDER_DATA_TABLE, orderId, {
              発注ステータス: '送信済み',
              更新日時: new Date().toISOString(),
              更新者ID: 'current-user' // 実際のログインユーザーIDを使用
            });
            successCount++;
          } catch (error) {
            console.error(`発注ID ${orderId} の更新に失敗:`, error);
            errorCount++;
          }
        }
      }

      if (successCount > 0) {
        showMessage(`${successCount}件の発注を正常に送信しました`, 'success');

        // データを再読み込みして表示を更新
        const storeId = container.querySelector('#store-select').value;
        const allOrders = await window.aivicApi.list(ORDER_DATA_TABLE) || [];
        currentOrders = allOrders.filter(order => 
          order.店舗ID === storeId && 
          order.発注日 && 
          order.発注日.startsWith(today)
        );
        renderOrders(currentOrders);
      }

      if (errorCount > 0) {
        showMessage(`${errorCount}件の発注送信に失敗しました`, 'error');
      }

    } catch (error) {
      showMessage('発注送信処理中にエラーが発生しました', 'error');
    }
  });

  // 初期化処理
  async function init() {
    await initStoreSelect();
    await loadProducts();
  }

  init();
}

function(container, apiUrl, tables) {
