      return;
    }

    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id || r.商品コード}">
        <td><a href="#" class="product-detail-link" data-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名}</a></td>
        <td>${r.商品コード}</td>
        <td style="text-align: right;">${(r.予測需要量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.現在在庫 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.安全在庫 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.発注点 || 0).toLocaleString()}</td>
        <td style="text-align: right; font-weight: bold;">${(r.推奨発注量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">¥${((r.推奨発注量 || 0) * (r.単価 || 0)).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary create-order-btn" data-id="${r.商品ID}">発注作成</button>
        </td>
      </tr>
    `).join('');
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    if (!storeId) {
      showError('店舗を選択してください。');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください。');
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError('計算対象期間を設定してください。');
      return false;
    }
    if (new Date(periodStart) >= new Date(periodEnd)) {
      showError('期間の開始日は終了日より前に設定してください。');
      return false;
    }
    if (safetyStock < 0) {
      showError('安全在庫数は0以上の値を入力してください。');
      return false;
    }
    if (leadTime <= 0) {
      showError('リードタイムは1以上の値を入力してください。');
      return false;
    }
    if (reorderPoint < 0) {
      showError('発注点は0以上の値を入力してください。');
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    try {
      // 商品データ取得
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      if (!products) {
        showError('商品データの取得に失敗しました。');
        return;
      }

      // カテゴリでフィルタリング
      const categoryProducts = products.filter(p => 
        p.有効フラグ && 
        p.AI予測対象フラグ && 
        (category === '食品' ? p.商品名.includes('食') : 
         category === '日用品' ? p.商品名.includes('日用') || p.商品名.includes('洗剤') : 
         category === '衣料品' ? p.商品名.includes('衣') || p.商品名.includes('服') : true)
      );

      if (categoryProducts.length === 0) {
        showError('選択したカテゴリに該当する商品がありません。');
        return;
      }

      // 需要予測データ取得
      const forecasts = await window.aivicApi.list(FORECAST_TABLE);
      if (!forecasts) {
        showError('需要予測データの取得に失敗しました。');
        return;
      }

      // 店舗・期間・商品でフィルタリング
      const relevantForecasts = forecasts.filter(f => 
        f.店舗ID === storeId &&
        new Date(f.予測対象日) >= new Date(periodStart) &&
        new Date(f.予測対象日) <= new Date(periodEnd) &&
        categoryProducts.some(p => p.id === f.商品ID)
      );

      if (relevantForecasts.length === 0) {
        showError('該当する需要予測データがありません。');
        return;
      }

      // 需要予測結果表示
      displayForecastData(relevantForecasts);

      // 在庫データ表示
      displayCurrentStock(categoryProducts);

      // 商品別に予測需要を集計して発注量計算
      const productForecasts = {};
      relevantForecasts.forEach(f => {
        if (!productForecasts[f.商品ID]) {
          productForecasts[f.商品ID] = {
            商品ID: f.商品ID,
            予測需要量: 0,
            予測精度: 0,
            count: 0
          };
        }
        productForecasts[f.商品ID].予測需要量 += f.予測数量 || 0;
        productForecasts[f.商品ID].予測精度 += f.予測精度 || 0;
        productForecasts[f.商品ID].count++;
      });

      // 計算結果生成
      calculationResults = Object.values(productForecasts).map(pf => {
        const product = categoryProducts.find(p => p.id === pf.商品ID);
        if (!product) return null;

        const avgAccuracy = pf.count > 0 ? pf.予測精度 / pf.count : 0;
        const currentStock = Math.floor(Math.random() * 500) + 50; // 仮の在庫数
        const dailyDemand = pf.予測需要量 / Math.max(1, (new Date(periodEnd) - new Date(periodStart)) / (1000 * 60 * 60 * 24));
        const leadTimeDemand = dailyDemand * leadTime;
        const calculatedReorderPoint = Math.max(reorderPoint, leadTimeDemand + safetyStock);

        // 発注量計算: 現在在庫が発注点を下回る場合に発注
        let recommendedOrder = 0;
        if (currentStock <= calculatedReorderPoint) {
          // 経済発注量の簡易計算（需要量の1.5倍を上限とする）
          const maxOrder = Math.ceil(pf.予測需要量 * 1.5);
          const minOrder = Math.max(product.最小発注数量 || 1, leadTimeDemand + safetyStock - currentStock);
          recommendedOrder = Math.min(maxOrder, Math.ceil(minOrder / (product.発注単位 || 1)) * (product.発注単位 || 1));
        }

        return {
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: Math.round(pf.予測需要量),
          現在在庫: currentStock,
          安全在庫: safetyStock,
          発注点: Math.round(calculatedReorderPoint),
          推奨発注量: recommendedOrder,
          単価: product.単価 || 0,
          予測精度: Math.round(avgAccuracy)
        };
      }).filter(r => r !== null);

      renderResults(calculationResults);
      showSuccess(`${calculationResults.length}商品の発注量計算が完了しました。`);

    } catch (error) {
      console.error('計算エラー:', error);
      showError('発注量計算中にエラーが発生しました。');
    }
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#period-start').value = '';
    container.querySelector('#period-end').value = '';
    container.querySelector('#safety-stock').value = '';
    container.querySelector('#lead-time').value = '';
    container.querySelector('#reorder-point').value = '';

    // 表示エリアもクリア
    container.querySelector('#forecast-display').innerHTML = '<p class="muted">計算条件を設定して「計算実行」ボタンをクリックしてください。</p>';
    container.querySelector('#current-stock-display').innerHTML = '<p class="muted">店舗と商品カテゴリを選択すると在庫情報が表示されます。</p>';

    calculationResults = [];
    renderResults([]);
  }

  // 発注作成
  async function createOrder(productId) {
    const result = calculationResults.find(r => r.商品ID === productId);
    if (!result || result.推奨発注量 <= 0) {
      showError('発注量が0のため発注を作成できません。');
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (parseInt(container.querySelector('#lead-time').value) || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: result.推奨発注量,
      予測数量: result.予測需要量,
      発注単価: result.単価,
      発注金額: result.推奨発注量 * result.単価,
      発注方法: 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: 'default-supplier',
      発注理由: 'AI需要予測に基づく自動発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(ORDER_TABLE, orderData);
    if (saved) {
      showSuccess(`${result.商品名}の発注を作成しました。`);
    } else {
      showError('発注の作成に失敗しました。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', executeCalculation);
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 商品詳細リンク
    const detailLink = e.target.closest('.product-detail-link');
    if (detailLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      showSuccess('商品詳細画面への遷移機能は今後実装予定です。');
      return;
    }

    // 発注作成ボタン
    const orderBtn = e.target.closest('.create-order-btn');
    if (orderBtn) {
      await createOrder(orderBtn.dataset.id);
      return;
    }
  });

  // 初期化
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#period-start').value = today.toISOString().split('T')[0];
  container.querySelector('#period-end').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#lead-time').value = '7';
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const resultCount = container.querySelector("#result-count");

  let allInventoryData = [];
  let storesData = [];
  let productsData = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case "不足":
        return "background: rgba(255, 106, 106, 0.2); color: #ff6a6a; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 165, 0, 0.2); color: #ffa500; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "適正":
        return "background: rgba(34, 197, 94, 0.2); color: #22c55e; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "color: var(--text-muted);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryRows) {
    if (!inventoryRows || inventoryRows.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" style="text-align: center; color: var(--text-muted); padding: 40px;">
            該当する商品が見つかりませんでした
          </td>
        </tr>
      `;
      resultCount.textContent = "0";
      return;
    }

    tbody.innerHTML = inventoryRows.map(row => {
      const product = productsData.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const statusStyle = getStatusStyle(status);

      return `
        <tr data-id="${row.在庫ID || row.id}">
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td style="text-align: right; ${currentStock === 0 ? 'color: #ff6a6a; font-weight: 600;' : ''}">${currentStock.toLocaleString()}</td>
          <td style="text-align: right;">${safetyStock.toLocaleString()}</td>
          <td><span style="${statusStyle}">${status}</span></td>
          <td style="color: var(--text-muted); font-size: 12px;">${row.更新日時 ? new Date(row.更新日時).toLocaleString() : ""}</td>
        </tr>
      `;
    }).join("");

    resultCount.textContent = inventoryRows.length.toString();
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storesData = stores.filter(store => store.有効フラグ);
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          storesData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productsData = products.filter(product => product.有効フラグ);

        // カテゴリ一覧を作成（重複除去）
        const categories = [...new Set(productsData.map(p => p.商品カテゴリID).filter(Boolean))];
        categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>' +
          categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join("");
      }
    } catch (error) {
      console.error("商品データの読み込みに失敗しました:", error);
    }
  }

  // 検索実行
  async function performSearch() {
    const selectedStoreId = storeSelect.value;

    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    try {
      // 在庫データを取得（実際のシステムでは在庫テーブルから取得）
      // ここではサンプルデータを生成
      const inventoryData = productsData.map(product => ({
        在庫ID: `inv-${product.商品ID}`,
        店舗ID: selectedStoreId,
        商品ID: product.商品ID,
        現在在庫数: Math.floor(Math.random() * 200),
        安全在庫数: Math.floor(Math.random() * 50) + 10,
        更新日時: new Date().toISOString()
      }));

      allInventoryData = inventoryData;

      // フィルタリング実行
      applyFilters();

    } catch (error) {
      console.error("検索に失敗しました:", error);
      showError("検索処理でエラーが発生しました");
    }
  }

  // フィルタ適用
  function applyFilters() {
    let filteredData = [...allInventoryData];

    // 商品カテゴリフィルタ
    const selectedCategory = categoryFilter.value;
    if (selectedCategory) {
      const categoryProducts = productsData.filter(p => p.商品カテゴリID === selectedCategory);
      const categoryProductIds = categoryProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => categoryProductIds.includes(inv.商品ID));
    }

    // 商品名検索
    const productNameKeyword = productNameSearch.value.trim();
    if (productNameKeyword) {
      // 特殊文字チェック
      if (/<script|javascript:|on\w+=/i.test(productNameKeyword)) {
        showError("不正な文字が含まれています");
        return;
      }

      // 最大文字数チェック
      if (productNameKeyword.length > 255) {
        showError("商品名は255文字以内で入力してください");
        return;
      }

      const matchingProducts = productsData.filter(p => 
        p.商品名 && p.商品名.includes(productNameKeyword)
      );
      const matchingProductIds = matchingProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => matchingProductIds.includes(inv.商品ID));
    }

    // 商品コード検索
    const productCodeKeyword = productCodeSearch.value.trim();
    if (productCodeKeyword) {
      // 特殊文字チェック
      if (/<script|javascript:|on\w+=/i.test(productCodeKeyword)) {
        showError("不正な文字が含まれています");
        return;
      }

      // 数値以外の文字チェック（英数字は許可）
      if (!/^[A-Za-z0-9]+$/.test(productCodeKeyword)) {
        showError("商品コードは英数字で入力してください");
        return;
      }

      // 最大桁数チェック
      if (productCodeKeyword.length > 20) {
        showError("商品コードは20桁以内で入力してください");
        return;
      }

      const matchingProducts = productsData.filter(p => 
        p.商品コード && p.商品コード.includes(productCodeKeyword)
      );
      const matchingProductIds = matchingProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => matchingProductIds.includes(inv.商品ID));
    }

    // 在庫状況フィルタ
    const selectedStatus = stockStatusFilter.value;
    if (selectedStatus) {
      filteredData = filteredData.filter(inv => {
        const status = getStockStatus(inv.現在在庫数, inv.安全在庫数);
        return status === selectedStatus;
      });
    }

    renderRows(filteredData);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!allInventoryData || allInventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = allInventoryData.map(row => {
      const product = productsData.find(p => p.商品ID === row.商品ID) || {};
      const status = getStockStatus(row.現在在庫数, row.安全在庫数);

      return [
        product.商品コード || "",
        product.商品名 || "",
        row.現在在庫数 || 0,
        row.安全在庫数 || 0,
        status,
        row.更新日時 ? new Date(row.更新日時).toLocaleString() : ""
      ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(",");
    });

    const csvContent = "\uFEFF" + [headers.join(","), ...csvData].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 検索条件クリア
  function clearSearchConditions() {
    storeSelect.value = "";
    categoryFilter.value = "";
    productNameSearch.value = "";
    productCodeSearch.value = "";
    stockStatusFilter.value = "";
    allInventoryData = [];
    tbody.innerHTML = `
      <tr>
        <td colspan="6" style="text-align: center; color: var(--text-muted); padding: 40px;">
          店舗を選択して検索してください
        </td>
      </tr>
    `;
    resultCount.textContent = "0";
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // リアルタイムフィルタリング
  categoryFilter.addEventListener("change", () => {
    if (allInventoryData.length > 0) {
      applyFilters();
    }
  });

  stockStatusFilter.addEventListener("change", () => {
    if (allInventoryData.length > 0) {
      applyFilters();
    }
  });

  // 初期データ読み込み
  loadStores();
  loadProducts();
}

