    }

    tbody.innerHTML = products.map(product => {
      const forecast = demandForecasts.find(f => f.商品ID === product.商品ID) || {};
      const predictedDemand = forecast.予測数量 || 0;
      const recommendedOrder = forecast.推奨発注数量 || 0;
      const currentStock = Math.floor(Math.random() * 100); // 仮の在庫数

      return `
        <tr data-product-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}" /></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>${currentStock}</td>
          <td><input type="number" class="input order-quantity" min="0" step="1" value="${recommendedOrder}" data-product-id="${product.商品ID}" data-unit-price="${product.単価 || 0}" /></td>
          <td>${product.単価 || 0}円</td>
          <td class="order-amount" data-product-id="${product.商品ID}">${(recommendedOrder * (product.単価 || 0)).toLocaleString()}円</td>
        </tr>
      `;
    }).join('');

    // 数量変更時の金額計算
    tbody.querySelectorAll('.order-quantity').forEach(input => {
      input.addEventListener('input', calculateAmount);
      input.addEventListener('blur', validateQuantity);
    });

    // チェックボックス変更時の合計計算
    tbody.querySelectorAll('.product-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', calculateTotal);
    });

    calculateTotal();
  }

  // 数量入力時の金額計算
  function calculateAmount(e) {
    const input = e.target;
    const productId = input.dataset.productId;
    const unitPrice = parseInt(input.dataset.unitPrice) || 0;
    const quantity = parseInt(input.value) || 0;
    const amount = quantity * unitPrice;

    const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
    if (amountCell) {
      amountCell.textContent = amount.toLocaleString() + '円';
    }

    calculateTotal();
  }

  // 数量バリデーション
  function validateQuantity(e) {
    const input = e.target;
    const value = input.value.trim();

    // 文字列チェック
    if (isNaN(value) || value === '') {
      alert('数値を入力してください');
      input.focus();
      return false;
    }

    const num = parseFloat(value);

    // 負の値チェック
    if (num < 0) {
      alert('発注数量は正の値を入力してください');
      input.focus();
      return false;
    }

    // ゼロチェック
    if (num === 0) {
      // ゼロは警告のみ（エラーではない）
      return true;
    }

    // 小数点チェック
    if (num !== Math.floor(num)) {
      alert('発注数量は整数で入力してください');
      input.focus();
      return false;
    }

    return true;
  }

  // 合計金額計算
  function calculateTotal() {
    let total = 0;
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');

    checkedBoxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const unitPrice = parseInt(quantityInput.dataset.unitPrice) || 0;
      const quantity = parseInt(quantityInput.value) || 0;
      total += quantity * unitPrice;
    });

    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // 商品データを読み込み
  async function loadProducts() {
    if (!currentStoreId) return;

    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);

    if (products) {
      allProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
    }

    if (forecasts) {
      demandForecasts = forecasts.filter(f => 
        f.店舗ID === currentStoreId && 
        f.予測対象日 && 
        new Date(f.予測対象日).toDateString() === new Date(currentOrderDate).toDateString()
      );
    }

    applyFilter();
  }

  // フィルター適用
  function applyFilter() {
    const categoryFilter = container.querySelector('#category-filter').value;

    filteredProducts = allProducts.filter(product => {
      if (categoryFilter && product.商品カテゴリID !== categoryFilter) {
        return false;
      }
      return true;
    });

    renderOrderItems(filteredProducts);
  }

  // 発注実行
  async function executeOrder() {
    // バリデーション
    if (!currentStoreId) {
      alert('店舗を選択してください');
      return;
    }

    if (!currentOrderDate) {
      alert('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    const orderDate = new Date(currentOrderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (orderDate < today) {
      alert('発注日付は本日以降の日付を選択してください');
      return;
    }

    // 選択された商品を取得
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    const orderItems = [];
    let hasError = false;

    checkedBoxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);

      if (!validateQuantity({ target: quantityInput })) {
        hasError = true;
        return;
      }

      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity === 0) {
        alert('発注数量は1以上の値を入力してください');
        hasError = true;
        return;
      }

      const product = allProducts.find(p => p.商品ID === productId);
      const forecast = demandForecasts.find(f => f.商品ID === productId);

      orderItems.push({
        商品ID: productId,
        商品名: product.商品名,
        商品コード: product.商品コード,
        発注数量: quantity,
        発注単価: product.単価 || 0,
        発注金額: quantity * (product.単価 || 0),
        予測数量: forecast?.予測数量 || 0
      });
    });

    if (hasError || orderItems.length === 0) {
      return;
    }

    // 確認ダイアログ表示
    showConfirmDialog(orderItems);
  }

  // 確認ダイアログ表示
  function showConfirmDialog(orderItems) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const totalAmount = orderItems.reduce((sum, item) => sum + item.発注金額, 0);

    content.innerHTML = `
      <div style="margin-bottom: 1rem;">
        <strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}<br>
        <strong>発注日付:</strong> ${currentOrderDate}
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>発注数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td>${item.商品コード}</td>
                <td>${item.商品名}</td>
                <td>${item.発注数量}</td>
                <td>${item.発注単価.toLocaleString()}円</td>
                <td>${item.発注金額.toLocaleString()}円</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div style="text-align: right; margin-top: 1rem; font-weight: bold;">
        合計金額: ${totalAmount.toLocaleString()}円
      </div>
    `;

    dialog.classList.remove('hidden');

    // 確認ダイアログのイベント
    container.querySelector('#btn-confirm-execute').onclick = () => confirmExecuteOrder(orderItems);
    container.querySelector('#btn-confirm-cancel').onclick = () => dialog.classList.add('hidden');
  }

  // 発注実行確定
  async function confirmExecuteOrder(orderItems) {
    try {
      const currentUser = 'user-001'; // 仮のユーザーID

      for (const item of orderItems) {
        const forecast = demandForecasts.find(f => f.商品ID === item.商品ID);

        const orderData = {
          店舗ID: currentStoreId,
          商品ID: item.商品ID,
          需要予測結果ID: forecast?.予測結果ID || null,
          発注日: currentOrderDate,
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // 3日後
          発注数量: item.発注数量,
          予測数量: item.予測数量,
          発注単価: item.発注単価,
          発注金額: item.発注金額,
          発注方法: item.発注数量 === item.予測数量 ? 'AI推奨採用' : 'AI推奨修正',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001', // 仮の仕入先ID
          発注理由: 'AI需要予測に基づく発注',
          承認者ID: currentUser,
          承認日時: new Date().toISOString(),
          自動発注フラグ: false,
          作成者ID: currentUser,
          更新者ID: currentUser
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      container.querySelector('#order-confirm-dialog').classList.add('hidden');
      alert('発注が正常に実行されました');

      // 画面をリセット
      container.querySelectorAll('.product-checkbox').forEach(cb => cb.checked = false);
      calculateTotal();

    } catch (error) {
      alert('発注処理中にエラーが発生しました');
      console.error(error);
    }
  }

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
    });
    calculateTotal();
  });

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    if (currentStoreId) {
      loadProducts();
    } else {
      renderOrderItems([]);
    }
  });

  // 発注日付変更
  container.querySelector('#order-date').addEventListener('change', (e) => {
    currentOrderDate = e.target.value;
    if (currentStoreId) {
      loadProducts();
    }
  });

  // カテゴリフィルター変更
  container.querySelector('#category-filter').addEventListener('change', applyFilter);

  // 表示更新ボタン
  container.querySelector('#btn-filter').addEventListener('click', () => {
    if (currentStoreId) {
      loadProducts();
    }
  });

  // 発注実行ボタン
  container.querySelector('#btn-execute-order').addEventListener('click', executeOrder);

  // 初期化
  loadStores();
  loadCategories();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'rank';
  let sortDirection = 'asc';

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // 精度ランキングテーブルの再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => {
      const accuracy = row.予測精度 || (100 - (row.MAPE || 0));
      const mapeColor = (row.MAPE || 0) > 20 ? '#dc3545' : (row.MAPE || 0) > 15 ? '#ff6a00' : '#28a745';
      const accuracyColor = accuracy < 80 ? '#dc3545' : accuracy < 90 ? '#ff6a00' : '#28a745';

      return `
        <tr data-id="${row.予測結果ID || row.id || index}">
          <td>${index + 1}</td>
          <td>${row.店舗名 || '不明'}</td>
          <td>${row.商品カテゴリ || '全般'}</td>
          <td style="color: ${mapeColor}; font-weight: bold;">${(row.MAPE || 0).toFixed(2)}%</td>
          <td>${(row.RMSE || 0).toFixed(2)}</td>
          <td style="color: ${accuracyColor}; font-weight: bold;">${accuracy.toFixed(1)}%</td>
          <td>${row.期間 || '過去1ヶ月'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID || row.id || index}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 予測精度推移グラフの描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1週前', '6日前', '5日前', '4日前', '3日前', '2日前', '昨日'];
    const mapeData = [18.5, 17.2, 16.8, 15.9, 16.3, 15.7, 15.25];
    const rmseData = [9.2, 8.8, 8.5, 8.1, 8.3, 8.0, 8.42];

    // グラフエリア設定
    const padding = 60;
    const graphWidth = width - padding * 2;
    const graphHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // MAPE線の描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < mapeData.length; i++) {
      const x = padding + (i * graphWidth) / (mapeData.length - 1);
      const y = height - padding - ((mapeData[i] - 10) / 15) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('MAPE (%)', padding, 20);
    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 60, 12, 20, 12);
  }

  // 予測vs実績比較チャートの描画
  function drawForecastActualChart() {
    const canvas = container.querySelector('#forecast-actual-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1週前', '6日前', '5日前', '4日前', '3日前', '2日前', '昨日'];
    const forecastData = [120, 135, 118, 142, 128, 155, 138];
    const actualData = [115, 140, 122, 138, 132, 148, 145];

    const padding = 60;
    const graphWidth = width - padding * 2;
    const graphHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 予測値線の描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < forecastData.length; i++) {
      const x = padding + (i * graphWidth) / (forecastData.length - 1);
      const y = height - padding - ((forecastData[i] - 100) / 60) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 実績値線の描画
    ctx.strokeStyle = '#28a745';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i * graphWidth) / (actualData.length - 1);
      const y = height - padding - ((actualData[i] - 100) / 60) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding, 20);
    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 50, 12, 20, 12);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', padding + 80, 20);
    ctx.fillStyle = '#28a745';
    ctx.fillRect(padding + 130, 12, 20, 12);
  }

  // データソート
  function sortData(data, column, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[column] || 0;
      let bVal = b[column] || 0;

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorContent = container.querySelector('#error-content');
    errorContent.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentData || currentData.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['順位', '店舗名', '商品カテゴリ', 'MAPE (%)', 'RMSE', '予測精度 (%)', '期間'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map((row, index) => [
        index + 1,
        `"${row.店舗名 || '不明'}"`,
        `"${row.商品カテゴリ || '全般'}"`,
        (row.MAPE || 0).toFixed(2),
        (row.RMSE || 0).toFixed(2),
        (row.予測精度 || (100 - (row.MAPE || 0))).toFixed(1),
        `"${row.期間 || '過去1ヶ月'}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // データ読み込み
  async function loadData() {
    try {
      hideError();
      const forecastData = await window.aivicApi.list(4); // 需要予測結果

      if (!forecastData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // サンプルデータで補完
      const sampleData = [
        { 店舗名: '店舗A', 商品カテゴリ: '食品', MAPE: 15.25, RMSE: 8.42, 予測精度: 84.75, 期間: '過去1ヶ月' },
        { 店舗名: '店舗B', 商品カテゴリ: '日用品', MAPE: 12.80, RMSE: 6.15, 予測精度: 87.20, 期間: '過去1ヶ月' },
        { 店舗名: '店舗C', 商品カテゴリ: '衣料品', MAPE: 18.90, RMSE: 10.25, 予測精度: 81.10, 期間: '過去1ヶ月' },
        { 店舗名: '店舗A', 商品カテゴリ: '日用品', MAPE: 14.50, RMSE: 7.80, 予測精度: 85.50, 期間: '過去1ヶ月' },
        { 店舗名: '店舗B', 商品カテゴリ: '食品', MAPE: 16.75, RMSE: 9.20, 予測精度: 83.25, 期間: '過去1ヶ月' }
      ];

      currentData = sampleData;
      renderRankingTable(currentData);
      drawAccuracyTrendChart();
      drawForecastActualChart();

    } catch (error) {
      showError('データの読み込み中にエラーが発生しました: ' + error.message);
    }
  }

  // 初期化
  initStoreOptions();
  loadData();

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const period = container.querySelector('#period-select').value;
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    try {
      hideError();
      await loadData();

      // フィルタリング処理
      let filteredData = [...currentData];

      if (storeId) {
        const selectedStore = tables[1]?.records?.find(s => s.店舗ID === storeId);
        if (selectedStore) {
          filteredData = filteredData.filter(d => d.店舗名 === selectedStore.店舗名);
        } else {
          showError('指定された店舗が見つかりません');
          return;
        }
      }

      if (category) {
        filteredData = filteredData.filter(d => d.商品カテゴリ === category);
      }

      currentData = filteredData;
      renderRankingTable(currentData);

    } catch (error) {
      showError('検索処理中にエラーが発生しました: ' + error.message);
    }
  });

  // エクスポートボタンのイベントリスナー
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 詳細分析ボタンのイベントリスナー
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // 再試行ボタンのイベントリスナー
  container.querySelector('#btn-retry').addEventListener('click', loadData);

  // テーブルソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('.sortable');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'asc';
      }

      const columnMap = {
        'rank': 'MAPE',
        'store': '店舗名',
        'category': '商品カテゴリ',
        'mape': 'MAPE',
        'rmse': 'RMSE',
        'accuracy': '予測精度',
        'period': '期間'
      };

      const sortedData = sortData(currentData, columnMap[column], sortDirection);
      renderRankingTable(sortedData);
    }

    // 詳細ボタンクリック
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });

  // オフライン状態の検出
  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });

  window.addEventListener('online', () => {
    hideError();
  });
}

function(container, apiUrl, tables) {
  let editingModelId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗名 || ""}</td>
        <td>${r.商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.精度目標値 || ""}%</td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">設定変更</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧を読み込み
  function loadStores() {
    const storeSelect = container.querySelector("#target-store");
    if (tables[1] && tables[1].records) {
      storeSelect.innerHTML = '<option value="">選択してください</option>' + 
        tables[1].records.map(store => 
          `<option value="${store.id}">${store.店舗名}</option>`
        ).join("");
    }
  }

  // 重み付け合計値を計算・表示
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll(".weight-input");
    let total = 0;
    weightInputs.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    container.querySelector("#weight-total").textContent = total;

    // 100%でない場合は警告表示
    const totalElement = container.querySelector("#weight-total");
    if (total !== 100) {
      totalElement.style.color = "#ff6a6a";
    } else {
      totalElement.style.color = "var(--text)";
    }
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector("#learning-rate");
    const display = container.querySelector("#learning-rate-value");
    display.textContent = parseFloat(slider.value).toFixed(5);
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // モデル名チェック
    const modelName = container.querySelector("#model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    // 対象店舗チェック
    const targetStore = container.querySelector("#target-store").value;
    if (!targetStore) {
      errors.push("対象店舗を選択してください");
    }

    // 商品カテゴリチェック
    const categories = container.querySelectorAll("#product-categories input:checked");
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    // 学習期間チェック
    const startDate = container.querySelector("#learning-start").value;
    const endDate = container.querySelector("#learning-end").value;
    if (!startDate || !endDate) {
      errors.push("学習期間を設定してください");
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > end) {
        errors.push("開始日は終了日より前の日付を設定してください");
      }
      if (start > today || end > today) {
        errors.push("学習期間に未来の日付は設定できません");
      }
    }

    // データソースチェック
    const dataSources = container.querySelectorAll("#data-sources input:checked");
    if (dataSources.length === 0) {
      errors.push("データソースを選択してください");
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector("#algorithm").value;
    if (!algorithm) {
      errors.push("アルゴリズムを選択してください");
    }

    // 精度目標値チェック
    const accuracyTarget = parseInt(container.querySelector("#accuracy-target").value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push("モデル精度目標値は0-100%の範囲で入力してください");
    }

    // 重み付け合計チェック
    const weightInputs = container.querySelectorAll(".weight-input");
    let weightTotal = 0;
    weightInputs.forEach(input => {
      weightTotal += parseInt(input.value) || 0;
    });
    if (weightTotal !== 100) {
      errors.push("重み付けの合計値は100%にしてください");
    }

    // 季節性パラメータの数値チェック
    const seasonalFactor = container.querySelector("#seasonal-factor").value;
    if (seasonalFactor && isNaN(parseFloat(seasonalFactor))) {
      errors.push("季節性パラメータには数値を入力してください");
    }

    return errors;
  }

  // フォームクリア
  function clearForm() {
    container.querySelector("#model-form").reset();
    container.querySelector("#form-title").textContent = "新規モデル作成";
    container.querySelector("#btn-save").textContent = "モデル作成";
    editingModelId = null;
    updateWeightTotal();
    updateLearningRateDisplay();
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });

  // 店舗データ読み込み
  loadStores();

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.trim();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = keyword ? 
        rows.filter(r => JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())) : 
        rows;
      renderRows(filtered);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["モデル名", "対象店舗名", "商品カテゴリ", "アルゴリズム", "精度目標値", "作成日時"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        `"${r.モデル名 || ""}"`,
        `"${r.対象店舗名 || ""}"`,
        `"${r.商品カテゴリ || ""}"`,
        `"${r.アルゴリズム || ""}"`,
        `"${r.精度目標値 || ""}"`,
        `"${r.作成日時 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_config_export.csv";
    link.click();
  });

  // 4. 登録ボタンのイベントリスナー
  container.querySelector("#btn-save").addEventListener("click", async (e) => {
    e.preventDefault();

    const errors = validateForm();

    // 既存のエラーメッセージを削除
    container.querySelectorAll(".error-message").forEach(el => el.remove());

    if (errors.length > 0) {
      const errorDiv = document.createElement("div");
      errorDiv.className = "error-message";
      errorDiv.innerHTML = errors.map(err => `• ${err}`).join("<br>");
      container.querySelector(".form-actions").insertBefore(errorDiv, container.querySelector(".form-actions").firstChild);
      return;
    }

    // フォームデータ収集
    const categories = Array.from(container.querySelectorAll("#product-categories input:checked"))
      .map(cb => cb.value).join(", ");
    const dataSources = Array.from(container.querySelectorAll("#data-sources input:checked"))
      .map(cb => cb.value).join(", ");
    const predictionPeriod = container.querySelector("input[name='prediction-period']:checked").value;

    const formData = {
      モデル名: container.querySelector("#model-name").value.trim(),
      対象店舗ID: container.querySelector("#target-store").value,
      対象店舗名: container.querySelector("#target-store").selectedOptions[0]?.textContent || "",
      商品カテゴリ: categories,
      学習期間開始日: container.querySelector("#learning-start").value,
      学習期間終了日: container.querySelector("#learning-end").value,
      予測期間: predictionPeriod,
      データソース: dataSources,
      アルゴリズム: container.querySelector("#algorithm").value,
      学習率: parseFloat(container.querySelector("#learning-rate").value),
      重み付け設定: JSON.stringify({
        売上履歴: parseInt(container.querySelector("input[data-factor='売上履歴']").value),
        天候要因: parseInt(container.querySelector("input[data-factor='天候要因']").value),
        季節要因: parseInt(container.querySelector("input[data-factor='季節要因']").value),
        イベント要因: parseInt(container.querySelector("input[data-factor='イベント要因']").value)
      }),
      季節係数: parseFloat(container.querySelector("#seasonal-factor").value),
      異常値除外フラグ: container.querySelector("#exclude-outliers").checked,
      精度目標値: parseInt(container.querySelector("#accuracy-target").value),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      const successDiv = document.createElement("div");
      successDiv.className = "success-message";
      successDiv.textContent = editingModelId ? 
        "モデル設定が正常に変更されました" : 
        "モデルが正常に作成されました";
      container.querySelector(".form-actions").insertBefore(successDiv, container.querySelector(".form-actions").firstChild);

      clearForm();
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    clearForm();
  });

  // 重み付け入力の監視
  container.querySelectorAll(".weight-input").forEach(input => {
    input.addEventListener("input", updateWeightTotal);
  });

  // 学習率スライダーの監視
  container.querySelector("#learning-rate").addEventListener("input", updateLearningRateDisplay);

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このモデルを削除しますか？")) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const rows = await window.aivicApi.list(0);
      if (!rows) return;

      const model = rows.find(r => r.id === editBtn.dataset.id);
      if (!model) return;

      // フォームに値を設定
      container.querySelector("#model-name").value = model.モデル名 || "";
      container.querySelector("#target-store").value = model.対象店舗ID || "";

      // 商品カテゴリ設定
      const categories = (model.商品カテゴリ || "").split(", ");
      container.querySelectorAll("#product-categories input").forEach(cb => {
        cb.checked = categories.includes(cb.value);
      });

      // 学習期間設定
      container.querySelector("#learning-start").value = model.学習期間開始日 || "";
      container.querySelector("#learning-end").value = model.学習期間終了日 || "";

      // 予測期間設定
      if (model.予測期間) {
        const periodRadio = container.querySelector(`input[name='prediction-period'][value='${model.予測期間}']`);
        if (periodRadio) periodRadio.checked = true;
      }

      // データソース設定
      const dataSources = (model.データソース || "").split(", ");
      container.querySelectorAll("#data-sources input").forEach(cb => {
        cb.checked = dataSources.includes(cb.value);
      });

      // その他の設定
      container.querySelector("#algorithm").value = model.アルゴリズム || "";
      container.querySelector("#learning-rate").value = model.学習率 || 0.01;
      container.querySelector("#seasonal-factor").value = model.季節係数 || 100;
      container.querySelector("#exclude-outliers").checked = model.異常値除外フラグ || false;
      container.querySelector("#accuracy-target").value = model.精度目標値 || 85;

      // 重み付け設定
      if (model.重み付け設定) {
        try {
          const weights = JSON.parse(model.重み付け設定);
          Object.keys(weights).forEach(factor => {
            const input = container.querySelector(`input[data-factor='${factor}']`);
            if (input) input.value = weights[factor];
          });
        } catch (e) {
          console.warn("重み付け設定のパースに失敗:", e);
        }
      }

      // フォームタイトル変更
      container.querySelector("#form-title").textContent = "モデル設定変更";
      container.querySelector("#btn-save").textContent = "保存";
      editingModelId = editBtn.dataset.id;

      updateWeightTotal();
      updateLearningRateDisplay();

      // フォームまでスクロール
      container.querySelector("#model-form").scrollIntoView({ behavior: "smooth" });
    }
  });

  // 初期値設定
  updateWeightTotal();
  updateLearningRateDisplay();
}

function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.テスト日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧の初期化
  function initStoreList() {
    const storeList = container.querySelector("#store-list");
    const storeTable = tables.find(t => t.tableName === "店舗マスタ");
    if (storeTable && storeTable.records) {
      storeList.innerHTML = storeTable.records.map(store => `
        <label><input type="checkbox" name="store" value="${store.id}"> ${store.店舗名 || store.店舗コード}</label>
      `).join("");
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション
  function validateTestSettings() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll('input[name="store"]:checked');
    const selectedCategories = container.querySelectorAll('input[name="category"]:checked');
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (modelSelect === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      showError("商品カテゴリが未選択です。商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // テスト実行
  function executeTest() {
    if (!validateTestSettings()) return;

    // テスト実行中の表示
    const executeBtn = container.querySelector("#btn-test-execute");
    executeBtn.textContent = "テスト実行中...";
    executeBtn.disabled = true;

    // 模擬的なテスト実行（実際のAI処理をシミュレート）
    setTimeout(() => {
      // 精度指標の更新
      container.querySelector("#mape-value").textContent = "12.5";
      container.querySelector("#rmse-value").textContent = "8.3";
      container.querySelector("#mae-value").textContent = "6.7";
      container.querySelector("#r2-value").textContent = "0.85";
      container.querySelector("#execution-time").textContent = "2分15秒";

      // モデルパラメータの表示
      const parametersDiv = container.querySelector("#model-parameters");
      parametersDiv.textContent = `学習率: 0.001
バッチサイズ: 32
エポック数: 100
隠れ層数: 3
ドロップアウト率: 0.2
最適化手法: Adam
損失関数: MSE`;

      // グラフの描画
      drawComparisonChart();

      // テスト履歴に追加
      const newTest = {
        id: Date.now().toString(),
        テスト日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll('input[name="store"]:checked').length,
        MAPE: "12.5%",
        RMSE: "8.3",
        実行時間: "2分15秒"
      };

      window.aivicApi.save(0, newTest).then(() => {
        window.aivicApi.list(0).then(renderTestHistory);
      });

      executeBtn.textContent = "テスト実行";
      executeBtn.disabled = false;
    }, 3000);
  }

  // グラフ描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズ設定
    canvas.width = 800;
    canvas.height = 400;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = "#1a2332";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = "#374151";
    ctx.lineWidth = 1;

    // 縦線
    for (let i = 0; i <= 10; i++) {
      const x = (canvas.width / 10) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvas.height);
      ctx.stroke();
    }

    // 横線
    for (let i = 0; i <= 8; i++) {
      const y = (canvas.height / 8) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // サンプルデータ
    const actualData = [120, 135, 110, 145, 160, 155, 140, 165, 150, 175];
    const predictedData = [115, 140, 105, 150, 155, 160, 135, 170, 145, 180];

    // 実績値の線
    ctx.strokeStyle = "#60a5fa";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = (canvas.width / (actualData.length - 1)) * i;
      const y = canvas.height - (actualData[i] / 200) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線
    ctx.strokeStyle = "#f87171";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = (canvas.width / (predictedData.length - 1)) * i;
      const y = canvas.height - (predictedData[i] / 200) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "14px sans-serif";
    ctx.fillText("実績値", 20, 30);
    ctx.fillText("予測値", 20, 50);

    ctx.fillStyle = "#60a5fa";
    ctx.fillRect(80, 22, 20, 2);
    ctx.fillStyle = "#f87171";
    ctx.fillRect(80, 42, 20, 2);
  }

  // CSVエクスポート
  function exportTestResults() {
    window.aivicApi.list(0).then(rows => {
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(row => [
          row.テスト日時 || "",
          row.モデル名 || "",
          row.テスト期間 || "",
          row.対象店舗数 || "",
          row.MAPE || "",
          row.RMSE || "",
          row.実行時間 || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(renderTestHistory);

  // 店舗一覧初期化
  initStoreList();

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const storeCheckboxes = container.querySelectorAll('input[name="store"]');
    storeCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全カテゴリ選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const categoryCheckboxes = container.querySelectorAll('input[name="category"]');
    categoryCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", executeTest);

  // エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", exportTestResults);

  // 行レベル操作（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      window.aivicApi.list(0).then(renderTestHistory);
      return;
    }

    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      // 詳細表示（実装例）
      alert("テスト詳細画面を表示します（ID: " + viewBtn.dataset.id + "）");
      return;
    }
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let validationPassed = false;
  let isProcessing = false;

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // ログ追加関数
  function addLog(message) {
    const logContent = container.querySelector('#log-content');
    const timestamp = new Date().toLocaleString();
    logContent.textContent += `[${timestamp}] ${message}\n`;
    logContent.scrollTop = logContent.scrollHeight;
  }

  // 進捗更新関数
  function updateProgress(percent, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    progressBar.style.width = percent + '%';
    progressText.textContent = `${percent}% - ${message}`;
  }

  // モデル一覧を読み込み
  async function loadModels() {
    // 需要予測結果テーブルから利用可能なモデルを取得
    const predictions = await window.aivicApi.list(4); // 需要予測結果テーブル
    if (!predictions) return;

    // モデルバージョンでグループ化
    const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン).filter(v => v))];
    currentModels = modelVersions.map((version, index) => ({
      id: `model_${index}`,
      name: `AI需要予測モデル v${version}`,
      version: version,
      created: new Date().toISOString(),
      accuracy: Math.floor(Math.random() * 20) + 80 // 80-99%のランダム精度
    }));

    const select = container.querySelector('#select-model');
    select.innerHTML = '<option value="">-- モデルを選択してください --</option>';
    currentModels.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
      select.appendChild(option);
    });
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (!stores) return;

    currentStores = stores.filter(s => s.有効フラグ);
    const storeList = container.querySelector('#store-list');
    storeList.innerHTML = '';

    currentStores.forEach(store => {
      const label = document.createElement('label');
      label.style.cssText = 'display: flex; align-items: center; gap: 8px; margin: 4px 0; cursor: pointer;';
      label.innerHTML = `
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
        <span>${store.店舗名} (${store.店舗コード})</span>
      `;
      storeList.appendChild(label);
    });
  }

  // モデル詳細表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (!model) {
      container.querySelector('#model-details').classList.add('hidden');
      return;
    }

    container.querySelector('#model-name').textContent = model.name;
    container.querySelector('#model-version').textContent = model.version;
    container.querySelector('#model-created').textContent = new Date(model.created).toLocaleString();
    container.querySelector('#model-accuracy').textContent = model.accuracy + '%';
    container.querySelector('#model-details').classList.remove('hidden');
  }

  // 影響範囲分析
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked').length;
    const estimatedProducts = selectedStores * 150; // 店舗あたり平均150商品と仮定
    const estimatedDuration = Math.ceil(selectedStores * 2.5); // 店舗あたり2.5分と仮定

    container.querySelector('#impact-stores').textContent = selectedStores;
    container.querySelector('#impact-products').textContent = estimatedProducts;
    container.querySelector('#impact-duration').textContent = `約${estimatedDuration}分`;

    let level = '低';
    if (selectedStores > 10) level = '中';
    if (selectedStores > 50) level = '高';
    container.querySelector('#impact-level').textContent = level;

    if (selectedStores > 0) {
      container.querySelector('#impact-analysis').classList.remove('hidden');
    } else {
      container.querySelector('#impact-analysis').classList.add('hidden');
    }
  }

  // バリデーション実行
  async function runValidation() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');

    if (!modelId) {
      showError('適用対象モデルを選択してください');
      return;
    }

    if (selectedStores.length === 0) {
      showError('適用対象店舗を選択してください');
      return;
    }

    container.querySelector('#validation-results').classList.remove('hidden');
    const statusDiv = container.querySelector('#validation-status');
    const detailsDiv = container.querySelector('#validation-details');

    statusDiv.innerHTML = '<strong>検証ステータス:</strong> <span style="color: #ffc107;">実行中...</span>';
    detailsDiv.innerHTML = '<div style="color: var(--text-muted);">検証を実行しています...</div>';

    // 模擬検証処理
    await new Promise(resolve => setTimeout(resolve, 2000));

    const validationSuccess = Math.random() > 0.2; // 80%の確率で成功
    validationPassed = validationSuccess;

    if (validationSuccess) {
      statusDiv.innerHTML = '<strong>検証ステータス:</strong> <span style="color: #28a745;">成功</span>';
      detailsDiv.innerHTML = `
        <div style="color: #28a745;">✓ データ品質チェック: 正常</div>
        <div style="color: #28a745;">✓ 精度閾値チェック: 正常</div>
        <div style="color: #28a745;">✓ 互換性チェック: 正常</div>
        <div style="color: #28a745;">✓ リソースチェック: 正常</div>
      `;
      container.querySelector('#btn-execute').disabled = false;
    } else {
      statusDiv.innerHTML = '<strong>検証ステータス:</strong> <span style="color: #dc3545;">失敗</span>';
      detailsDiv.innerHTML = `
        <div style="color: #28a745;">✓ データ品質チェック: 正常</div>
        <div style="color: #dc3545;">✗ 精度閾値チェック: 閾値を下回っています</div>
        <div style="color: #28a745;">✓ 互換性チェック: 正常</div>
        <div style="color: #28a745;">✓ リソースチェック: 正常</div>
      `;
      container.querySelector('#btn-execute').disabled = true;
      showError('適用前検証でエラーが発生しました。モデルの精度が閾値を下回っています。');
    }
  }

  // モデル適用実行
  async function executeModelDeployment() {
    const startDateTime = container.querySelector('#input-start-datetime').value;

    if (!startDateTime) {
      showError('適用開始日時を入力してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();

    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-execute').disabled = true;
    container.querySelector('#btn-validate').disabled = true;
    container.querySelector('#progress-section').classList.remove('hidden');
    container.querySelector('#log-section').classList.remove('hidden');

    addLog('モデル本番適用処理を開始します');

    // 段階的な処理実行
    const steps = [
      { percent: 10, message: 'バックアップ作成中', delay: 1000 },
      { percent: 25, message: 'モデル検証中', delay: 1500 },
      { percent: 40, message: 'デプロイメント準備中', delay: 1000 },
      { percent: 60, message: 'モデル配布中', delay: 2000 },
      { percent: 80, message: '本番切替中', delay: 1500 },
      { percent: 100, message: '適用完了', delay: 500 }
    ];

    for (const step of steps) {
      updateProgress(step.percent, step.message);
      addLog(step.message);
      await new Promise(resolve => setTimeout(resolve, step.delay));
    }

    // 適用結果の保存（システム操作履歴に記録）
    const selectedStoreIds = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    const modelId = container.querySelector('#select-model').value;

    await window.aivicApi.save(9, { // システム操作履歴
      ユーザーID: 'current-user-id',
      操作種別: 'モデル本番適用',
      操作画面: 'モデル本番適用処理',
      操作内容: `モデル${modelId}を${selectedStoreIds.length}店舗に適用`,
      処理結果: '成功',
      操作日時: new Date().toISOString()
    });

    addLog('モデル本番適用が正常に完了しました');
    container.querySelector('#rollback-section').classList.remove('hidden');
    isProcessing = false;
  }

  // ロールバック実行
  async function executeRollback() {
    if (!confirm('前バージョンのモデルにロールバックしますか？')) {
      return;
    }

    container.querySelector('#progress-section').classList.remove('hidden');
    updateProgress(0, 'ロールバック準備中');
    addLog('ロールバック処理を開始します');

    const steps = [
      { percent: 20, message: 'バックアップ確認中', delay: 800 },
      { percent: 50, message: '前バージョン復元中', delay: 1500 },
      { percent: 80, message: 'サービス切替中', delay: 1000 },
      { percent: 100, message: 'ロールバック完了', delay: 500 }
    ];

    for (const step of steps) {
      updateProgress(step.percent, step.message);
      addLog(step.message);
      await new Promise(resolve => setTimeout(resolve, step.delay));
    }

    addLog('ロールバックが正常に完了しました');

    // ロールバック記録
    await window.aivicApi.save(9, {
      ユーザーID: 'current-user-id',
      操作種別: 'モデルロールバック',
      操作画面: 'モデル本番適用処理',
      操作内容: '前バージョンのモデルにロールバック実行',
      処理結果: '成功',
      操作日時: new Date().toISOString()
    });
  }

  // 初期化
  loadModels();
  loadStores();

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // イベントリスナー
  container.querySelector('#select-model').addEventListener('change', (e) => {
    showModelDetails(e.target.value);
    validationPassed = false;
    container.querySelector('#btn-execute').disabled = true;
    container.querySelector('#validation-results').classList.add('hidden');
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();

      // 全店舗選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.store-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all-stores');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  container.querySelector('#btn-validate').addEventListener('click', runValidation);
  container.querySelector('#btn-execute').addEventListener('click', executeModelDeployment);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // ページ離脱時の警告
  window.addEventListener('beforeunload', (e) => {
    if (isProcessing) {
      e.preventDefault();
      e.returnValue = 'モデル適用処理が実行中です。ページを離れますか？';
    }
  });
}
